### What version of Hono are you using?

hono: 4.11.7 @hono/node-server: 1.19.9

### What runtime/platform is your app running on? (with version if possible)

Bun 1.2.19 (Linux) Also reproduced on Node.js v22.17.1

### What steps can reproduce the bug?

## Cause 
When @hono/node-server's serve() runs with overrideGlobalObjects: true (the default), it replaces globalThis.Request and globalThis.Response with lightweight polyfills. Libraries that validate objects via instanceof Request or instanceof Response break silently because the objects returned by native fetch() were constructed with the original classes, not Hono's replacements.

## Reproduce 
- run the bun test to reproduce
```shell
bun test client-server.test.ts 
bun test v1.2.19 (aad3abea)

client-server.test.ts:
[client-server] globalThis.Request === NativeRequest? false
--> GET http://localhost:19100/api/v1/secrets
<-- 200 http://localhost:19100/api/v1/secrets
✓ openapi-fetch + @hono/node-server overrideGlobalObjects > returning response from middleware throws "must return new Response()" [228.00ms]
[client-server] globalThis.Request === NativeRequest? true
--> GET http://localhost:19100/api/v1/secrets
<-- 200 http://localhost:19100/api/v1/secrets
✓ openapi-fetch + @hono/node-server overrideGlobalObjects > NOT returning from middleware bypasses instanceof check (the fix) [204.00ms]

 2 pass
 0 fail
 7 expect() calls
Ran 2 tests across 1 file. [543.00ms]
```
- test file
```typescript
import { describe, test, expect, beforeAll, afterAll, afterEach } from 'bun:test';
import { Hono } from 'hono';
import { serve, type ServerType } from '@hono/node-server';
import createClient, { type Middleware } from 'openapi-fetch';

type Paths = {
  '/api/v1/secrets': {
    get: {
      responses: {
        200: {
          content: {
            'application/json': { data: Record<string, string> };
          };
        };
      };
    };
  };
};

const MOCK_PORT = 19_100;
const CLIENT_PORT = 19_101;

const OriginalRequest = globalThis.Request;
const OriginalResponse = globalThis.Response;

const middleware: Middleware = {
  async onRequest({ request }) {
    console.log(`--> ${request.method} ${request.url}`);
    return request;
  },
  async onResponse({ response }) {
    console.log(`<-- ${response.status} ${response.url}`);
    return response;
  },
};

function buildMockApp() {
  const app = new Hono();
  app.get('/api/v1/secrets', (c) =>
    c.json({
      data: {
        apiKey: 'sk-live-XXXXXXXXXXXXXXXX',
        dbPassword: 'super-secret-p@ssw0rd',
        encryptionKey: 'aes-256-gcm-key-material',
      },
    }),
  );
  return app;
}

describe('openapi-fetch + @hono/node-server overrideGlobalObjects', () => {
  let mockRemoteServer: ReturnType<typeof Bun.serve>;
  let clientServer: ServerType | undefined;

  beforeAll(() => {
    mockRemoteServer = Bun.serve({ port: MOCK_PORT, fetch: buildMockApp().fetch });
  });

  afterEach(() => {
    clientServer?.close();
    clientServer = undefined;
    globalThis.Request = OriginalRequest;
    globalThis.Response = OriginalResponse;
  });

  afterAll(()=>{
    mockRemoteServer?.stop();
  })

  test('returning response from middleware throws "must return new Response()"', async () => {
    const apiClient = createClient<Paths>({
      baseUrl: `http://localhost:${MOCK_PORT}`,
    });

    apiClient.use(middleware);

    const app = new Hono();
    app.get('/fetch-secrets', async (c) => {
      try {
        const { data, error } = await apiClient.GET('/api/v1/secrets');
        if (error) return c.json({ error: 'upstream_error' }, 502);
        return c.json(data);
      } catch (err) {
        return c.json(
          { error: 'middleware_failure', message: String(err) },
          500,
        );
      }
    });

    clientServer = serve({
      fetch: app.fetch,
      port: CLIENT_PORT,
      // default overrideGlobalObjects: true,
    },
    (info) =>{
      console.log('[client-server] globalThis.Request === NativeRequest?', globalThis.Request === OriginalRequest);
    });
    await Bun.sleep(200);

    expect(globalThis.Response).not.toBe(OriginalResponse);

    const res = await fetch(
      `http://localhost:${CLIENT_PORT}/fetch-secrets`,
    );
    const body = (await res.json()) as { error: string; message: string };

    expect(res.status).toBe(500);
    expect(body.error).toBe('middleware_failure');
    expect(body.message).toContain(
      'onResponse: must return new Response() when modifying the response',
    );
  });

  test('NOT returning from middleware bypasses instanceof check (the fix)', async () => {
    const apiClient = createClient<Paths>({
      baseUrl: `http://localhost:${MOCK_PORT}`,
    });

    apiClient.use(middleware);

    const app = new Hono();
    app.get('/fetch-secrets', async (c) => {
      const { data, error } = await apiClient.GET('/api/v1/secrets');
      if (error) return c.json({ error: 'upstream_error' }, 502);
      return c.json(data);
    });

    clientServer = serve({
      fetch: app.fetch,
      port: CLIENT_PORT,
      overrideGlobalObjects: false,
    },
    (info) =>{
      console.log('[client-server] globalThis.Request === NativeRequest?', globalThis.Request === OriginalRequest);
    });
    await Bun.sleep(200);

    const res = await fetch(
      `http://localhost:${CLIENT_PORT}/fetch-secrets`,
    );
    const body = (await res.json()) as { data: Record<string, string> };

    expect(res.status).toBe(200);
    expect(body.data.apiKey).toBe('sk-live-XXXXXXXXXXXXXXXX');
    expect(body.data.dbPassword).toBe('super-secret-p@ssw0rd');
  });
});
```

### What is the expected behavior?

serve() should not break instanceof checks in third-party libraries. Returning the same Request/Response object from middleware callbacks should work regardless of overrideGlobalObjects.

